'use strict';
let transactions=read('sagi-fuel',[]),parsedStatement=null,pendingImport=null;
const mapFields=[['date','Purchase date',true,['date','transactiondate','purchasedate']],['station','Station / location',false,['station','merchant','merchantname','location']],['gallons','US gallons',true,['gallons','quantity','volume']],['total','Diesel total (USD)',false,['fueltotal','total','amount','transactionamount']],['price','Unit price (USD / US gallon)',false,['unitprice','price','pricepergallon','ppg']],['id','Transaction ID',false,['transactionid','transactionnumber','invoice','reference']],['currency','Currency',false,['currency','currencycode']],['product','Fuel product',false,['product','fueltype','productname']]];
const providerSaved=read('sagi-provider','EFS/WEX');if([...$('provider').options].some(o=>o.value===providerSaved))$('provider').value=providerSaved;
function providerStatus(){$('providerStatus').innerHTML=`<span class="provider-tag">${esc($('provider').value)} · Setup required</span>`;}providerStatus();
$('provider').onchange=()=>{persist('sagi-provider',$('provider').value);providerStatus();pendingImport=null;$('importPreview').innerHTML='';};
$('fuelFile').onchange=async()=>{pendingImport=null;parsedStatement=null;$('importPreview').innerHTML='';$('mappingForm').hidden=true;const file=$('fuelFile').files[0];if(!file)return;if(file.size>2*1024*1024){$('importStatus').textContent='Choose a statement smaller than 2 MB.';return}try{parsedStatement=FuelCore.parseCSV(await file.text());$('importStatus').textContent=`${parsedStatement.rows.length} rows found. Match the columns, then review before importing.`;$('mappingFields').innerHTML=mapFields.map(([key,label,required,aliases])=>{let selected=parsedStatement.header.findIndex(h=>aliases.includes(h.toLowerCase().replace(/[^a-z]/g,'')));return `<label>${label}${required?' *':''}<select id="map_${key}" ${required?'required':''}><option value="">${required?'Choose a column':'Not included'}</option>${parsedStatement.header.map((h,i)=>`<option value="${i}" ${i===selected?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`}).join('');$('confirmUnits').checked=false;$('mappingForm').hidden=false;}catch(e){$('importStatus').textContent=e.message;}};
$('mappingForm').onchange=()=>{pendingImport=null;$('importPreview').innerHTML='';};
$('mappingForm').onsubmit=e=>{e.preventDefault();const map={};mapFields.forEach(([k])=>map[k]=$('map_'+k).value);const chosen=Object.values(map).filter(v=>v!=='');if(new Set(chosen).size!==chosen.length){toast('Each selected field needs its own column.');return}if(map.total===''&&map.price===''){toast('Map either a diesel total or a unit price.');return}pendingImport=FuelCore.review(parsedStatement,map,$('provider').value,transactions);const r=pendingImport,t=FuelCore.totals(r.valid);$('importPreview').innerHTML=`<div class="note"><b>${r.valid.length} ready to import · ${r.duplicates.length} duplicates skipped · ${r.invalid.length} invalid rows excluded</b>${money(t.total)} diesel purchases · ${t.gallons.toFixed(2)} US gallons</div>${r.invalid.length?`<details><summary>Review excluded rows</summary><div class="review-scroll">${r.invalid.map(x=>`<p>Row ${x.row}: ${esc(x.error)}</p>`).join('')}</div></details>`:''}<div class="review-scroll">${r.valid.slice(0,8).map(t=>`<div class="row"><span>${esc(t.date)} · ${esc(t.station)}</span><b>${money(t.total)}</b></div>`).join('')}${r.valid.length>8?'<p>Showing first 8 valid rows.</p>':''}</div><button class="primary" id="commitImport" ${r.valid.length?'':'disabled'}>Import ${r.valid.length} valid transactions</button>`;$('commitImport').onclick=()=>{if(!pendingImport?.valid.length)return;const next=[...transactions,...pendingImport.valid.map(t=>({...t,id:crypto.randomUUID(),tripId:'',importedAt:new Date().toISOString()}))];if(!persist('sagi-fuel',next))return;transactions=next;pendingImport=null;parsedStatement=null;$('importPreview').innerHTML='';$('mappingForm').hidden=true;$('fuelFile').value='';$('importStatus').textContent='Import complete. Link purchases to saved trips below.';renderFuel();toast('Fuel transactions imported.');};};
function downloadCSV(name,rows){const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const u=URL.createObjectURL(new Blob([rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function tripLabel(s){return `${s.origin} → ${s.destination} · ${new Date(s.date).toLocaleDateString()}`;}
function renderFuel(){const t=FuelCore.totals(transactions);$('transactionCount').textContent=`${transactions.length} transactions`;$('fuelTotals').innerHTML=transactions.length?`<div class="purchase-metrics"><div><small>Fuel purchased</small><b>${money(t.total)}</b></div><div><small>US gallons</small><b>${t.gallons.toFixed(1)}</b></div><div><small>Weighted paid price / gal</small><b>${money(t.price)}</b></div></div>`:'<p class="hint">No fuel purchases imported yet.</p>';$('usePaidPrice').disabled=!transactions.length;$('exportFuel').disabled=!transactions.length;$('clearFuel').disabled=!transactions.length;$('transactionList').innerHTML=[...transactions].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<div class="transaction"><header><div><b>${esc(t.station)}</b><br><small>${esc(t.date)} · ${esc(t.provider)} · ${t.gallons.toFixed(2)} gal · ${money(t.price)}/gal</small></div><b>${money(t.total)}</b></header><label>Assign purchase to a saved trip<select data-transaction="${t.id}"><option value="">Unassigned</option>${saved.map(s=>`<option value="${s.id}" ${String(t.tripId)===String(s.id)?'selected':''}>${esc(tripLabel(s))}</option>`).join('')}</select></label></div>`).join('');$('transactionList').querySelectorAll('select').forEach(select=>select.onchange=()=>{const next=transactions.map(t=>t.id===select.dataset.transaction?{...t,tripId:select.value}:t);if(persist('sagi-fuel',next)){transactions=next;toast('Trip assignment updated.');}else renderFuel();});}window.renderFuel=renderFuel;renderFuel();
$('usePaidPrice').onclick=()=>{const t=FuelCore.totals(transactions);if(!t.gallons)return;$('price').value=t.price.toFixed(3);tab('plan');if(last)calculate();toast('Fuel assumption updated from imported purchases; not a current quote.');};
$('exportFuel').onclick=()=>{if(!transactions.length)return;downloadCSV('Truckload-fuel-purchases.csv',[['Date','Station','Gallons','Fuel Total','Unit Price','Transaction ID','Currency','Product','Provider','Assigned trip'],...transactions.map(t=>[t.date,t.station,t.gallons,t.total,t.price.toFixed(4),t.transactionId,'USD','Diesel',t.provider,tripLabel(saved.find(s=>String(s.id)===String(t.tripId))||{origin:'Unassigned',destination:'',date:new Date().toISOString()})])]);};
$('clearFuel').onclick=()=>{if(!confirm('Remove imported fuel purchases from this device? Saved estimates and final costs will remain.'))return;if(persist('sagi-fuel',[])){transactions=[];pendingImport=null;$('importPreview').innerHTML='';renderFuel();toast('Imported purchases removed.');}};
function renderSaved(){
 $('savedList').innerHTML=saved.map((s,i)=>{const linked=transactions.filter(t=>String(t.tripId)===String(s.id)),t=FuelCore.totals(linked),actual=s.actual;return `<article class="trip-card"><h3>${esc(s.origin)} → ${esc(s.destination)}</h3><small>${new Date(s.date).toLocaleDateString()} · ${s.miles.toLocaleString()} total miles · Load pays ${money(s.pay)}</small><div class="grid"><div><small>Estimated earnings</small><h2>${money(s.net)}</h2></div><div><small>Fuel purchases assigned</small><h2>${linked.length?money(t.total):'None yet'}</h2></div></div><p class="hint">Fuel purchases are cash spent, not necessarily fuel consumed on this trip. Link transactions under Fuel account.</p>${linked.length?`<div class="row"><span>Assigned purchases</span><b>${t.gallons.toFixed(1)} gallons · ${money(t.price)}/gal</b></div><div class="row"><span>Estimated consumed fuel cost</span><b>${money(s.fuel)}</b></div>`:''}${actual?`<div class="note"><b>Final earnings entered: ${money(actual.pay-actual.fuel-actual.other)}</b>Total final costs: ${money(actual.fuel+actual.other)} · ${money(actual.pay-actual.fuel-actual.other-s.net)} versus estimate<br>Before income tax. Based on your completed cost entries.</div>`:''}<details><summary>${actual?'Edit':'Enter'} final trip costs</summary><p class="hint">Enter the final payment, cost of fuel consumed on this trip, and all other trip costs. Include business fees, tolls, driver pay, and your overhead allocation. Assigned fuel purchases do not fill this in automatically.</p><form data-actual="${i}"><div class="grid"><label>Final load payment ($)<input name="actualPay" type="number" min="0" step="0.01" value="${actual?.pay??s.pay}" required></label><label>Consumed fuel cost ($)<input name="actualFuel" type="number" min="0" step="0.01" value="${actual?.fuel??''}" required></label><label>All other final trip costs ($)<input name="actualOther" type="number" min="0" step="0.01" value="${actual?.other??''}" required></label></div><button type="submit" class="primary">Save final costs</button></form></details><details><summary>Load details & appointments</summary><p>${esc(s.loadNumber||'No load number')} · ${esc(s.equipment||'Equipment not entered')} · ${esc(s.weight||'—')} lb</p><p>Pickup: ${esc(s.pickupAt||'Not entered')} · ${esc(s.pickupAddress||s.origin)}</p><p>Delivery: ${esc(s.deliveryAt||'Not entered')} · ${esc(s.deliveryAddress||s.destination)}</p><p>${esc(s.broker||'')}<br>${esc(s.notes||'')}</p></details><div class="actions"><button data-reuse="${i}">Plan a similar trip</button><button data-remove="${i}" class="text-button">Delete estimate</button></div></article>`}).join('')||'<div class="card">Your saved estimates will appear here. Start with Plan a trip.</div>';
 $('savedList').querySelectorAll('[data-actual]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f),i=+f.dataset.actual,next=saved.map((s,j)=>j===i?{...s,actual:{pay:+fd.get('actualPay'),fuel:+fd.get('actualFuel'),other:+fd.get('actualOther')}}:s);if(persist('sagi-trips',next)){saved=next;renderSaved();toast('Final costs saved.');}});
 $('savedList').querySelectorAll('[data-reuse]').forEach(b=>b.onclick=()=>{const s=saved[+b.dataset.reuse];$('tripForm').reset();window.setActiveRatecon?.(null);['origin','destination','pay','deadhead','days','price','tolls','extras','fees'].forEach(k=>$(k).value=s[k]);$('miles').value=s.loadedMiles??(s.miles-s.deadhead);last=null;tab('plan');calculate();toast('Route copied. Review current prices and trip details.');});
 $('savedList').querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const i=+b.dataset.remove;if(!confirm('Delete this estimate? Linked fuel purchases will remain and become unassigned.'))return;const id=saved[i].id,next=saved.filter((s,j)=>j!==i);if(persist('sagi-trips',next)){saved=next;transactions=transactions.map(t=>String(t.tripId)===String(id)?{...t,tripId:''}:t);persist('sagi-fuel',transactions);renderSaved();}});
}
$('export').onclick=()=>{if(!saved.length){toast('Save an estimate first.');return}downloadCSV('Truckload-trip-estimates.csv',[['Load number','Pickup appointment','Delivery appointment','Pickup address','Delivery address','Broker contact','Equipment','Weight lb','Instructions','Date','Pickup','Delivery','Estimated load pay USD','Total miles','Estimated cost USD','Estimated earnings USD','Assigned fuel purchases USD','Final load pay USD','Final consumed fuel cost USD','Final other costs USD','Final earnings USD'],...saved.map(s=>[s.loadNumber??'',s.pickupAt??'',s.deliveryAt??'',s.pickupAddress??'',s.deliveryAddress??'',s.broker??'',s.equipment??'',s.weight??'',s.notes??'',s.date,s.origin,s.destination,s.pay,s.miles,s.cost.toFixed(2),s.net.toFixed(2),FuelCore.totals(transactions.filter(t=>String(t.tripId)===String(s.id))).total.toFixed(2),s.actual?.pay??'',s.actual?.fuel??'',s.actual?.other??'',s.actual?(s.actual.pay-s.actual.fuel-s.actual.other).toFixed(2):''])]);};
